#include "MacTestSupport.h"
#include "Processor.h"
#include <iostream>
#include <thread>
#include <stdexcept>
using namespace studio;
void require(bool value,const char*message){if(!value)throw std::runtime_error(message);}
struct Head:juce::AudioPlayHead{bool playing=true,recording=false,known=true;juce::Optional<PositionInfo>getPosition()const override{if(!known)return{};PositionInfo p;p.setIsPlaying(playing);p.setIsRecording(recording);return p;}};
void run(Processor&p,juce::AudioBuffer<float>&b){const juce::ScopedLock lock(p.getCallbackLock());juce::MidiBuffer midi;p.processBlock(b,midi);}
void zeros(Processor&p){juce::AudioBuffer<float>b(2,9000);b.clear();run(p,b);}
int impulse(Processor&p){zeros(p);juce::AudioBuffer<float>b(2,9000);b.clear();b.setSample(0,0,.5);b.setSample(1,0,.5);run(p,b);int peak=0;for(int i=1;i<b.getNumSamples();++i)if(std::abs(b.getSample(0,i))>std::abs(b.getSample(0,peak)))peak=i;require(std::abs(b.getSample(0,peak)-.5f)<1e-6,"dry impulse level");return peak;}
void pump(){struct Probe:juce::Timer{int calls=0;void timerCallback()override{++calls;}}probe;probe.startTimer(1);auto start=juce::Time::getMillisecondCounterHiRes();do{juce::Thread::sleep(5);juce::Timer::callPendingTimersSynchronously();}while((probe.calls<3||juce::Time::getMillisecondCounterHiRes()-start<100)&&juce::Time::getMillisecondCounterHiRes()-start<2000);require(probe.calls>=3,"timer dispatch missing");}
struct Listener:juce::AudioProcessorListener{int changes=0,mismatches=0;std::thread::id thread=std::this_thread::get_id();void audioProcessorParameterChanged(juce::AudioProcessor*,int,float)override{}void audioProcessorChanged(juce::AudioProcessor*p,const ChangeDetails&d)override{if(!d.latencyChanged)return;++changes;auto&q=static_cast<Processor&>(*p);if(impulse(q)!=p->getLatencySamples()||std::this_thread::get_id()!=thread)++mismatches;}};
void transitions(){for(int k=0;k<12;++k)for(int mode=0;mode<2;++mode){auto p=std::make_unique<Processor>(Kind(k));Head h;p->setPlayHead(&h);p->set("mix",0);p->set("gillQuality",float(mode));p->prepareToPlay(48000,31);require(impulse(*p)==p->getLatencySamples(),"initial reported/actual mismatch");Listener listener;p->addListener(&listener);const auto latency=p->getLatencySamples();p->set("gillQuality",float(1-mode));pump();require(p->pending()&&p->getLatencySamples()==latency,"switch while playing");h.playing=false;h.recording=true;zeros(*p);pump();require(p->pending(),"switch while recording");h.recording=false;zeros(*p);pump();require(!p->pending()&&p->appliedQuality()==1-mode&&listener.mismatches==0,"stopped commit ordering");require(impulse(*p)==p->getLatencySamples(),"switched actual latency");require(p->appliedQuality()!=0||p->getLatencySamples()==0,"LIVE buffer");p->removeListener(&listener);std::cout<<names[k]<<" mode "<<mode<<" transport transition passed\n";}}
juce::MemoryBlock encode(const juce::ValueTree&tree){juce::MemoryBlock b;juce::MemoryOutputStream out(b,false);tree.writeToStream(out);return b;}
void stateTests(){for(int k=0;k<12;++k){auto p=std::make_unique<Processor>(Kind(k));p->set("input",7);juce::MemoryBlock bytes;p->getStateInformation(bytes);const auto original=juce::ValueTree::readFromData(bytes.getData(),bytes.getSize());for(auto schema:{juce::var("1"),juce::var(1.5),juce::var(2),juce::var(-1)}){auto bad=original.createCopy();bad.setProperty("schema",schema,nullptr);for(auto child:bad)if(child.getProperty("id")==juce::var("input"))child.setProperty("value",-17,nullptr);auto data=encode(bad);p->setStateInformation(data.getData(),int(data.getSize()));require(std::abs(p->value("input")-7)<.001,"bad schema partially changed state");}auto partial=original.createCopy();for(int i=partial.getNumChildren()-1;i>=0;--i)if(partial.getChild(i).getProperty("id")==juce::var("input"))partial.removeChild(i,nullptr);auto data=encode(partial);p->setStateInformation(data.getData(),int(data.getSize()));require(p->value("input")==0,"missing parameter retained stale value");}}
juce::MouseEvent event(juce::Component&c,juce::Point<float>position,bool dragging=false){return{juce::Desktop::getInstance().getMainMouseSource(),position,juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier),1,0,0,0,0,&c,&c,juce::Time::getCurrentTime(),position,juce::Time::getCurrentTime(),1,dragging};}
void graphTests(){for(auto k:{Kind::Transient,Kind::Room}){auto p=std::make_unique<Processor>(k);p->prepareToPlay(48000,31);std::unique_ptr<juce::AudioProcessorEditor>e(p->createEditor());e->mouseDoubleClick(event(*e,{200,140}));require(p->value("b1_enable")>.5f,"double-click did not create a node");const float frequency=p->value("b1_frequency");e->mouseDown(event(*e,{200,140}));e->mouseDrag(event(*e,{420,132},true));e->mouseUp(event(*e,{420,132}));require(p->value("b1_frequency")>frequency*5&&p->value("b1_gain")>10,"graph drag does not edit frequency and gain");const auto q=p->value("b1_q");juce::MouseWheelDetails wheel;wheel.deltaY=.5f;e->mouseWheelMove(event(*e,{420,132}),wheel);require(p->value("b1_q")>q,"graph wheel does not edit Q");}}
int main(){gillInitialiseTestApplication();
  juce::ScopedJuceInitialiser_GUI gui;std::cout<<std::unitbuf;try{transitions();stateTests();graphTests();std::cout<<"STUDIO_TRANSITIONS_STATE_GRAPH_PASS\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
